cards.append(dict(id='S14',citation='Barndorff-Nielsen, Hansen, Lunde & Shephard (2008), Designing Realized Kernels to Measure the ex post Variation of Equity Prices in the Presence of Noise, Econometrica76(6),1481-1536; DOI10.3982/ECTA6495.',version='Published57-pagePDF accessed through author Harvard page in web reader. Local HTTP download returned403; no local PDF/hash claimed.',refs='Author-hosted PDFpp1-4 /journal1481-1483: copyright, estimator, weights and scope; https://shephard.scholars.harvard.edu/sites/g/files/omnuum7741/files/ecta08.pdf .',model='Efficient-price quadratic variation observed with market frictions; realized kernel corrects realized variance using symmetric lagged return autocovariances.',observation='Separate price-noise layer. The paper treats simple independent frictions and extensions to temporal dependence/endogeneity; assumptions depend on the selected theorem.',estimator='Kernel RV+weighted positive/negative realized autocovariances. Bandwidth/kernel smoothness determine rates and asymptotic variance; this is not ordinaryRV with a quarticity plug-in.',data='Simulation and NYSE illustration described in the introduction; exact empirical inputs not audited.',finding='A robust realized measure requires explicit noise/kernel/boundary conventions. It does not become ground truth merely because it is noise robust.',limits='Targeted initial-section inspection only. Exact bandwidth/end-correction conventions forSPYRM RK fields remain unresolved. Local acquisition was blocked and recorded.',replication='No realized-kernel implementation or table replication claimed. Source license permits noncommercial educational/research copying subject to its notice; no redistribution is performed.',adds='Prevents using ordinaryRV uncertainty formulas for every robust measure.'))
def main():
 (R/'literature/evidence_cards.json').write_text(json.dumps(cards,indent=2,ensure_ascii=False),encoding='utf8')
 titles={'citation':'Citation','version':'Version and status','refs':'Inspected source locations','model':'Model and assumptions','observation':'Observation and error layer','estimator':'Estimator and target','data':'Data and horizon','finding':'Source-grounded finding','limits':'Limitations and unresolved audit','replication':'Our replication status','adds':'Relevance and defensible extension'}
 for card in cards:
  s=f"# {card['id']} - targeted evidence card\n\nThis is a targeted methodological audit, not a claim that every source section has been fully checked.\n\n"
  s+='\n\n'.join('## '+title+'\n\n'+card[key] for key,title in titles.items())+'\n'
  (R/f"literature/cards/{card['id']}.md").write_text(s,encoding='utf8')
 print(len(cards),'targeted evidence cards written')
if __name__=='__main__':main()
